def eigenvector_centrality(adj, iters=100, tol=1e-6):
    # adj: {노드: [이웃]} 무방향 연결 그래프
    x = {v: 1.0 for v in adj}
    for _ in range(iters):
        # (A + I)x: 진동 방지, 고유벡터는 동일
        nx = {v: x[v] + sum(x[u] for u in adj[v])
              for v in adj}
        norm = sqrt(sum(s * s for s in nx.values()))
        nx = {v: s / norm for v, s in nx.items()}
        if max(abs(nx[v] - x[v]) for v in adj) < tol:
            return nx  # 수렴
        x = nx
    return x

eight-puzzle.pseudocode:
GOAL = (1, 2, 3, 4, 5, 6, 7, 8, 0)  # 0 = 빈칸

def h1(state):  # 제자리가 아닌 타일 수
    return sum(1 for i, t in enumerate(state)
               if t != 0 and t != GOAL[i])

def h2(state):  # 맨해튼 거리 합
    total = 0
    for i, t in enumerate(state):
        if t != 0:
            g = GOAL.index(t)
            total += abs(i//3 - g//3) + abs(i%3 - g%3)
    return total

def neighbors(state):  # 빈칸을 상하좌우로 이동
    z = state.index(0)
    r, c = divmod(z, 3)
    for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
        nr, nc = r + dr, c + dc
        if 0 <= nr < 3 and 0 <= nc < 3:
            s, n = list(state), nr * 3 + nc
            s[z], s[n] = s[n], s[z]
            yield tuple(s)
